      "A parenthesis with a subscript multiplies everything inside it: $\\mathrm{Ca(OH)_2}$ has 1 Ca, 2 O and 2 H. $\\mathrm{Al_2(SO_4)_3}$ has 2 Al, 3 S and 12 O (3 × 4 = 12 oxygens).",
      "Golden rule: the subscript defines WHICH substance it is ($\\mathrm{H_2O}$ is water and $\\mathrm{H_2O_2}$ is hydrogen peroxide); the coefficient only says HOW MUCH there is. That is why, to change an amount, you change the coefficient, never the subscript.",
