        pregunta: "How many electrons does the balanced half-reaction $\\mathrm{Cr_2O_7^{2-}}$ → 2$\\mathrm{Cr^{3+}}$ have?",
        opciones: ["3", "4", "6", "12"],
        respuesta: 2,
        explicacion: "On the left: −2 + 14 = +12; on the right: +6. 6 e⁻ are added on the left (the more positive side).",
