        respuesta: 2,
        explicacion: "Oxygens: 3 on the left and 1 on the right, so 2 H₂O on the right. Hydrogens: 4 H⁺ on the left. Charges: −1 + 4 = +3 versus 0, so 3 e⁻ on the left.",
