      "Shortcut for hydrocarbons: with only single bonds and an open chain (alkane) the formula is CₙH₂ₙ₊₂; with one double bond (alkene) it is CₙH₂ₙ; with one triple bond (alkyne) it is CₙH₂ₙ₋₂. A single ring (cycloalkane) is also CₙH₂ₙ.",
      "Each double bond, triple bond or ring (one unsaturation) removes 2 hydrogens compared with the alkane. To count how many there are: (2n + 2 − H) / 2. Benzene, $\\mathrm{C_6H_6}$, gives (2·6 + 2 − 6) / 2 = 4: three double bonds and one ring.",
